module.exports="-- LOCAL REVIEW PROPOSAL ONLY. Never imported by application startup/requests.\n-- Apply only after separate production metadata/snapshot review and authorization.\n-- Existing approved lesson sets are grandfathered, never expanded by this migration.\nCREATE TABLE course_workflows (\n offering_id INT NOT NULL PRIMARY KEY,\n state ENUM('DRAFT','SUBMITTED_FOR_REVIEW','CHANGES_REQUESTED','PUBLISHED') NOT NULL DEFAULT 'DRAFT',\n revision INT UNSIGNED NOT NULL DEFAULT 0,\n legacy_published BOOLEAN NOT NULL DEFAULT FALSE,\n feedback TEXT NULL,\n submitted_by INT NULL, submitted_at DATETIME NULL,\n reviewed_by INT NULL, reviewed_at DATETIME NULL,\n updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n FOREIGN KEY (offering_id) REFERENCES scholar_subjects(id)\n) ENGINE=InnoDB;\nCREATE TABLE course_workflow_uploads (\n id CHAR(36) NOT NULL PRIMARY KEY, offering_id INT NOT NULL,\n state ENUM('UPLOADING','RECONCILIATION_REQUIRED') NOT NULL,\n created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n FOREIGN KEY (offering_id) REFERENCES course_workflows(offering_id), INDEX (offering_id)\n) ENGINE=InnoDB;\n-- Review duplicates and published/pending structure BEFORE authorizing this seed.\nINSERT INTO course_workflows (offering_id,state,legacy_published)\n SELECT ss.id,IF(ss.approved=1 AND sp.approved=1 AND EXISTS\n (SELECT 1 FROM videos v WHERE v.subject_id=ss.subject_id AND v.scholar_user_id=ss.scholar_user_id AND v.approved=1),'PUBLISHED','DRAFT'),\n ss.approved=1 AND sp.approved=1 AND EXISTS\n (SELECT 1 FROM videos v WHERE v.subject_id=ss.subject_id AND v.scholar_user_id=ss.scholar_user_id AND v.approved=1)\n FROM scholar_subjects ss JOIN scholar_profile sp ON sp.user_id=ss.scholar_user_id;\n";
